metadata.content:
Use this full clean production-grade rewrite for preview-v2/vite.config.ts.
It fixes the real problem in your current file:
@/ → /projects/ ❌
which should be:
@/ → /projects/<projectId>/ ✅
It also keeps:


MIME-safe JS responses


isolated Vite config


dependency access to root node_modules


deterministic preflight + entry bridge



Bashcat > preview-v2/vite.config.ts <<'EOF'
import { defineConfig } from "vite";
import react from "@vitejs/plugin-react";
import path from "path";
import fs from "fs";

type PreflightResult = {
  ok: boolean;
  kind: string;
  message: string;
  details?: string;
  absoluteEntry?: string;
  projectRoot?: string;
};

export default defineConfig({
  root: __dirname,

  plugins: [
    react(),

    {
      name: "kore-preview-bridge",

      configureServer(server) {
        const projectsRoot = path.resolve(
          __dirname,
          "../runtime/workspaces/default/projects"
        );

        function normalizeEntry(entry: string) {
          return entry.replace(/^\/+/, "");
        }

        function isRenderableEntry(entry: string) {
          return /(^|\/)page\.(tsx|jsx)$/.test(entry);
        }

        function resolveRelativeImport(fromFile: string, spec: string): string | null {
          const base = path.resolve(path.dirname(fromFile), spec);

          const candidates = [
            base,
            `${base}.ts`,
            `${base}.tsx`,
            `${base}.js`,
            `${base}.jsx`,
            path.join(base, "index.ts"),
            path.join(base, "index.tsx"),
            path.join(base, "index.js"),
            path.join(base, "index.jsx"),
          ];

          for (const candidate of candidates) {
            if (fs.existsSync(candidate)) return candidate;
          }

          return null;
        }

        function scanImports(code: string): string[] {
          const matches = [
            ...code.matchAll(/from\s+["']([^"']+)["']/g),
            ...code.matchAll(/import\s+["']([^"']+)["']/g),
          ];

          return matches.map((m) => m[1]).filter(Boolean);
        }

        function diagnose(projectId: string, entry: string): PreflightResult {
          if (!projectId) {
            return {
              ok: false,
              kind: "missing_project",
              message: "Missing projectId.",
            };
          }

          if (!entry) {
            return {
              ok: false,
              kind: "missing_entry",
              message: "Missing entry file.",
            };
          }

          const normalizedEntry = normalizeEntry(entry);

          if (!isRenderableEntry(normalizedEntry)) {
            return {
              ok: false,
              kind: "unsupported_entry",
              message: `Unsupported entry: ${normalizedEntry}. Select a page.tsx/page.jsx file.`,
            };
          }

          const projectRoot = path.join(projectsRoot, projectId);
          const absoluteEntry = path.join(projectRoot, normalizedEntry);

          if (!fs.existsSync(absoluteEntry)) {
            return {
              ok: false,
              kind: "entry_not_found",
              message: `Entry not found: ${absoluteEntry}`,
            };
          }

          try {
            const code = fs.readFileSync(absoluteEntry, "utf8");
            const imports = scanImports(code);

            if (
              /\bserver-only\b/.test(code) ||
              /\bnext\/headers\b/.test(code) ||
              /\bnext-auth\b/.test(code) ||
              /\bdrizzle-orm\b/.test(code) ||
              /\b@neondatabase\/serverless\b/.test(code) ||
              /\bexport\s+default\s+async\s+function\b/.test(code)
            ) {
              return {
                ok: false,
                kind: "server_component",
                message:
                  "This page appears to use server-only or async App Router logic and cannot run in Preview v2.",
                details: absoluteEntry,
              };
            }

            for (const spec of imports) {
              if (spec.startsWith(".") || spec.startsWith("..")) {
                const resolved = resolveRelativeImport(absoluteEntry, spec);
                if (!resolved) {
                  return {
                    ok: false,
                    kind: "missing_relative_import",
                    message: `Missing relative import: ${spec}`,
                    details: absoluteEntry,
                  };
                }
              }
            }

            return {
              ok: true,
              kind: "ok",
              message: "Previewable entry detected.",
              absoluteEntry,
              projectRoot,
            };
          } catch (error) {
            return {
              ok: false,
              kind: "read_error",
              message:
                error instanceof Error
                  ? error.message
                  : "Failed to read entry file.",
            };
          }
        }

        function rewriteAliasesToFs(code: string, projectRoot: string) {
          const safeRoot = projectRoot.replace(/\\/g, "/");

          return code.replace(
            /from\s+["']@\/([^"']+)["']/g,
            (_match, subpath) => {
              const absolute = `/@fs/${safeRoot}/${subpath}`;
              return `from "${absolute}"`;
            }
          ).replace(
            /import\s+["']@\/([^"']+)["']/g,
            (_match, subpath) => {
              const absolute = `/@fs/${safeRoot}/${subpath}`;
              return `import "${absolute}"`;
            }
          );
        }

        server.middlewares.use("/__kore_preview_preflight", (req, res) => {
          try {
            const url = new URL(req.url || "", "http://localhost:5173");
            const projectId = url.searchParams.get("projectId") || "";
            const entry = url.searchParams.get("entry") || "";

            const result = diagnose(projectId, entry);

            res.statusCode = 200;
            res.setHeader("Content-Type", "application/json");
            res.end(JSON.stringify(result, null, 2));
          } catch (error) {
            const message =
              error instanceof Error ? error.message : "Preflight failed.";

            res.statusCode = 500;
            res.setHeader("Content-Type", "application/json");
            res.end(
              JSON.stringify(
                {
                  ok: false,
                  kind: "read_error",
                  message,
                },
                null,
                2
              )
            );
          }
        });

        server.middlewares.use("/__kore_preview_entry", (req, res) => {
          try {
            const url = new URL(req.url || "", "http://localhost:5173");
            const projectId = url.searchParams.get("projectId") || "";
            const entry = url.searchParams.get("entry") || "";

            const result = diagnose(projectId, entry);

            res.statusCode = 200;
            res.setHeader("Content-Type", "application/javascript");

            if (!result.ok) {
              res.end(`
                export const __koreReason = ${JSON.stringify(result.message)};
                export default null;
              `);
              return;
            }

            const absoluteEntry = String(result.absoluteEntry);
            const projectRoot = String(result.projectRoot);

            let source = fs.readFileSync(absoluteEntry, "utf8");
            source = rewriteAliasesToFs(source, projectRoot);

            const tempEntryDir = path.join(
              projectsRoot,
              projectId,
              ".kore-preview-v2"
            );
            fs.mkdirSync(tempEntryDir, { recursive: true });

            const tempEntryFile = path.join(
              tempEntryDir,
              `entry-${Date.now()}.tsx`
            );

            fs.writeFileSync(tempEntryFile, source, "utf8");

            const safeFsImport = `/@fs/${tempEntryFile.replace(/\\/g, "/")}`;

            res.end(`
              import * as Mod from ${JSON.stringify(safeFsImport)};

              export const __koreReason = "";

              const Candidate =
                typeof Mod.default === "function"
                  ? Mod.default
                  : typeof Mod.Page === "function"
                  ? Mod.Page
                  : null;

              export default Candidate;
            `);
          } catch (error) {
            const message =
              error instanceof Error ? error.message : "Preview entry error";

            res.statusCode = 200;
            res.setHeader("Content-Type", "application/javascript");
            res.end(`
              export const __koreReason = ${JSON.stringify(message)};
              export default null;
            `);
          }
        });
      },
    },
  ],

  css: {
    postcss: {
      plugins: [],
    },
  },

  resolve: {
    alias: [],
  },

  server: {
    host: "0.0.0.0",
    port: 5173,
    strictPort: true,
    fs: {
      allow: [
        path.resolve(__dirname),
        path.resolve(__dirname, "../runtime/workspaces/default/projects"),
        path.resolve(__dirname, "../node_modules"),
      ],
    },
    hmr: {
      overlay: true,
    },
  },

  optimizeDeps: {
    include: [
      "react",
      "react-dom",
      "clsx",
      "tailwind-merge",
      "class-variance-authority",
    ],
  },
});
EOF
Then restart clean:
Bashnpm run dev:all
Expected behavior after this:


repo-test should still render


korelumina-dogfood should either render or show a structured unsupported/build error


no more broken @/components/... path pointing at /projects/components/...


The next likely issue, if any, will be a server component / Next App Router limitation, not alias resolution.
